const out = $input.first().json;
const parsed = out.output && typeof out.output === 'object' ? out.output : out;

function clamp01(n) {
  const num = Number(n);
  if (!isFinite(num)) return 0;
  return Math.max(0, Math.min(1, num));
}

const intent = parsed.intent || 'off_topic';
const editField = parsed.edit_field || null;
let entries = Array.isArray(parsed.entries) ? parsed.entries : [];

entries = entries.map(e => {
  const confidence = {
    project: clamp01(e.confidence && e.confidence.project),
    activity: clamp01(e.confidence && e.confidence.activity),
    hours: clamp01(e.confidence && e.confidence.hours),
    work_date: clamp01(e.confidence && e.confidence.work_date)
  };

  let hours = e.hours;
  if (hours !== null && hours !== undefined) {
    const n = Number(hours);
    hours = isFinite(n) ? n : null;
    if (hours === null) confidence.hours = 0;
  } else {
    hours = null;
  }

  return {
    project: e.project || null,
    activity: e.activity || null,
    work_date: e.work_date || null,
    hours,
    task_description: e.task_description || null,
    additional_comments: e.additional_comments || null,
    confidence
  };
}).filter(e => {
  return e.project || e.activity || e.work_date || e.hours !== null || e.task_description || e.additional_comments;
});

return [{
  json: {
    intent,
    entries,
    edit_field: editField,
    prompt_version: 'worklog-lite-extract-v1',
    model: 'gemini-1.5-flash'
  }
}];
